/**
 * Generated per build by the build-info plugins in vite.config.ts and
 * esbuild.config.mjs, so the UI can show which build Figma has loaded.
 */
declare module "virtual:build-info" {
  /** package.json version */
  export const version: string;
  /** ISO timestamp of the build that produced this bundle */
  export const buildTime: string;
}
